  useEffect(() => { if (!allowed) return; let ignore = false; setLoading(true); setError(''); setMissing(false); fetchApprovalCandidates({ search, qualification, page }).then((d) => { if (!ignore) { setRows(d.rows); setCount(d.count); } }).catch((e) => { if (!ignore) { setError(e.message); setMissing(approvalBackendMissing(e)); } }).finally(() => { if (!ignore) setLoading(false); }); return () => { ignore = true; }; }, [allowed, search, qualification, page, version]);
  const refresh = () => setVersion((n) => n + 1);
