  return <div className="space-y-6 animate-fade-in min-w-0"><header className="flex flex-wrap justify-between gap-3 items-start"><div><p className="text-xs uppercase font-semibold text-primary-400">Manajemen Vendor</p><h1 className="text-2xl md:text-3xl font-semibold text-white mt-1 inline-flex items-center gap-2"><ShieldCheck size={25} /> Persetujuan Vendor</h1><p className="text-sm text-ink-400 mt-2">Tinjau identitas, lokasi dan QC. Catat keputusan terlebih dahulu, lalu lakukan aktivasi secara terpisah.</p></div><button className="btn-secondary text-sm" disabled={loading} onClick={refresh}><RefreshCw size={14} /> Refresh</button></header>
    <div className="card p-4 flex flex-col sm:flex-row gap-3"><div className="flex-1"><label className="label" htmlFor="approval-search">Cari nama / kode vendor</label><input id="approval-search" className="input" value={searchInput} onChange={(e) => setSearchInput(e.target.value)} /></div><div><label className="label" htmlFor="approval-qualification">Kelayakan kandidat</label><select id="approval-qualification" className="input" value={qualification} onChange={(e) => { setQualification(e.target.value); setPage(0); }}><option value="">Semua kelayakan</option>{Object.entries(QUALIFICATION_LABELS).map(([k, v]) => <option key={k} value={k}>{v}</option>)}</select></div></div>
    {missing ? <p role="status" className="card p-5 text-sm text-ink-400">Persetujuan dan aktivasi belum diaktifkan. Data vendor dan modul lainnya tetap tersedia.</p> : error ? <p role="alert" className="card p-5 text-sm text-danger-400">{error} <button className="underline" onClick={refresh}>Coba lagi</button></p> : loading ? <p role="status" className="card p-5 text-ink-400">Memuat kandidat…</p> : <div className="card overflow-hidden"><div className="overflow-x-auto"><table className="table"><thead><tr><th>Vendor</th><th>Kelayakan</th><th>Operasional</th><th>Aksi</th></tr></thead><tbody>{rows.map((c) => <tr key={c.id}><td><span className="font-mono text-xs text-ink-400">{c.candidate_code}</span><p className="text-white font-medium">{c.business_name}</p></td><td><span className={QUALIFICATION_BADGES[c.qualification_status]}>{QUALIFICATION_LABELS[c.qualification_status]}</span></td><td>{OPERATIONAL_LABELS[c.operational_status]}</td><td><button className="btn-secondary text-xs" aria-label={`Tinjau ${c.business_name}`} onClick={() => setSelected(c.id)}>Tinjau</button></td></tr>)}</tbody></table>{!rows.length && <p className="p-8 text-center text-sm text-ink-400">Tidak ada kandidat sesuai filter.</p>}</div><div className="flex flex-wrap justify-between gap-3 items-center p-4 text-xs text-ink-400 border-t border-white/10"><span>{count} profil · halaman {page + 1}</span><div className="flex gap-2"><button className="btn-secondary text-xs" disabled={!page} onClick={() => setPage((n) => n - 1)}>Sebelumnya</button><button className="btn-secondary text-xs" disabled={(page + 1) * 25 >= count} onClick={() => setPage((n) => n + 1)}>Berikutnya</button></div></div></div>}
    {selected && <Detail id={selected} onClose={() => setSelected('')} onChanged={refresh} />}
  </div>;
